function frame(){requestAnimationFrame(frame);let wall=clock.getDelta(),raw=Math.min(wall,.05),dt=raw;elapsed+=wall;fpsAccum+=wall;frameCount++;if(fpsAccum>=1){fps=frameCount/fpsAccum;frameCount=0;fpsAccum=0;}if(freeze>0){freeze-=raw;dt*=.15}oceanMat.uniforms.time.value=elapsed;sky.material.uniforms.time.value=elapsed;sky.position.copy(keeper.position);shotCooldown-=dt;dashCooldown-=dt;spawnTimer-=dt;sentryTimer-=dt;lightningTimer-=dt;shake*=.9;
if(lightningTimer<0){moon.intensity=6;lightningTimer=rand(6,15);tone(33,1,.15)}moon.intensity+=(2-moon.intensity)*dt*8;
let move=new T.Vector3((keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),0,(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0));move.applyAxisAngle(new T.Vector3(0,1,0),yaw);if(move.lengthSq()){if(firstAction===null)firstAction=performance.now()-started;move.normalize();keeper.position.addScaledVector(move,dt*(5+levels[5]*.5));walk+=dt*9;footTimer-=dt;if(footTimer<0){if(!(onBridge(keeper.position)&&playSfx('sfx_plank_step.ogg',.22,.9+Math.random()*.2)))tone(65,.06,.04,'triangle');footTimer=.34}}else walk+=dt;legs.forEach((l,i)=>l.rotation.x=Math.sin(walk+i*Math.PI)*(move.lengthSq()?.4:.03));coat.rotation.z=Math.sin(elapsed*5)*.035;lantern.rotation.z=Math.sin(elapsed*3)*.12;keeper.rotation.y=Math.atan2(aimDirection().x,aimDirection().z)+Math.PI;
if(levels[5]>=6&&keys.Space){vy=Math.min(vy+dt*25,7)}else vy-=dt*18;keeper.position.y+=vy*dt;groundY=onBridge(keeper.position)?0:-11;if(keeper.position.y<groundY){keeper.position.y=groundY;vy=0;}if(keeper.position.y< -8){health-=dt*22;if(health<5){keeper.position.set(0,1,19);health=100;toast('THE STORM RETURNS')}}
if(held){charge=Math.min(1,charge+dt*(.65+levels[4]*.09));glow.intensity=18+charge*35;}else glow.intensity=18+levels[0]*3;$('#bar b').style.width=charge*100+'%';
if(spawnTimer<=0&&enemies.filter(e=>e.hp>0).length<(quality==='Low'?14:23)){spawnTimer=Math.max(1.3,4-storm*.22);spawn();}storm=1+Math.floor(elapsed/25);if(mode==='siege'){siegeTime=Math.max(0,siegeTime-wall);if(siegeTime<35&&!window.leviathan){window.leviathan=true;spawn(true);toast('LEVIATHAN')}if(siegeTime===0){toast('SIEGE SURVIVED');siegeTime=300;cash+=200;window.leviathan=false;}}
for(let i=enemies.length-1;i>=0;i--){let e=enemies[i];if(e.hp<=0){e.falling+=dt;e.g.position.y-=dt*(4+e.falling*8);e.g.rotation.z+=dt*.8;if(e.falling>2){scene.remove(e.g);enemies.splice(i,1)}continue}if(e.g.position.y>=0&&brokenPlanks.some(b=>b.p.distanceTo(e.g.position)<1)){hit(e,999);continue;}if(e.g.position.y<0)e.g.position.y+=dt*4;else{let dir=keeper.position.clone().sub(e.g.position).setY(0),dist=dir.length();if(dist>1.8)e.g.position.addScaledVector(dir.normalize(),dt*e.speed);else{health-=dt*10;shake=Math.max(shake,.06);}}e.g.rotation.y=Math.atan2(keeper.position.x-e.g.position.x,keeper.position.z-e.g.position.z);e.g.rotation.z=Math.sin(elapsed*3+i)*.06;}
for(let i=bolts.length-1;i>=0;i--){let b=bolts[i];b.g.position.addScaledVector(b.v,dt);b.life-=dt;for(let e of enemies){if(e.hp>0&&!b.hit.has(e)&&e.g.position.distanceTo(b.g.position)<b.rad+e.r+1.4){b.hit.add(e);hit(e,b.damage);if(b.pierce--<=0)b.life=0;}}for(let p of props){if(p.hp>0&&p.g.position.distanceTo(b.g.position)<b.rad+(p.tower?6:1)){p.hp-=b.damage;if(p.hp<=0){burst(p.g.position,p.tower?65:25);loot(p.g.position,4);scene.remove(p.g);if(p.cargo){shatterFooting(p.g.position.clone().setY(0));}if(p.cargo)enemies.filter(e=>e.g.position.distanceTo(p.g.position)<10).forEach(e=>hit(e,180));}b.life=0;}}if(b.life<=0){burst(b.g.position,5);scene.remove(b.g);bolts.splice(i,1)}}
for(let i=salvages.length-1;i>=0;i--){let s=salvages[i];let target=keeper.position.clone().add(new T.Vector3(.6,1,0)),dist=s.g.position.distanceTo(target);s.life-=dt;if(dist<10+levels[2]*6){s.g.position.lerp(target,Math.min(1,dt*(3+levels[2])))}else{s.v.y-=dt*6;s.g.position.addScaledVector(s.v,dt);if(s.g.position.y<.5){s.g.position.y=.5;s.v.multiplyScalar(.9);s.v.y=0}}s.g.rotation.y+=dt*3;if(dist<1||s.life<=0){if(dist<1){cash+=2+levels[2];if(!salvageChime())tone(500+Math.random()*300,.06,.025);ui();save()}scene.remove(s.g);salvages.splice(i,1)}}
for(let i=0;i<debrisCount;i++){let d=debris[i];if(d.life>0){d.life-=dt;d.v.y-=dt*15;d.p.addScaledVector(d.v,dt);dummy.position.copy(d.p);dummy.rotation.set(elapsed*i*.1,elapsed,elapsed*.4);dummy.scale.set(d.s,d.s*.3,d.s*2);}else dummy.scale.setScalar(0);dummy.updateMatrix();debrisMesh.setMatrixAt(i,dummy.matrix)}debrisMesh.instanceMatrix.needsUpdate=true;
sentries.forEach((s,i)=>{s.visible=i<Math.ceil(levels[3]/2);s.position.copy(keeper.position).add(new T.Vector3(Math.cos(elapsed+i*1.57)*1.5,2.8,Math.sin(elapsed+i*1.57)*1.5));});if(levels[3]&&sentryTimer<0){sentryTimer=3/(1+levels[3]*.2);shoot(0,true,sentries[0].position)}
for(let i=0;i<rainCount;i++){rainPos[i*3+1]-=dt*23;rainPos[i*3]-=dt*4;if(rainPos[i*3+1]<-5){rainPos[i*3+1]=45;rainPos[i*3]=keeper.position.x+rand(-65,65);rainPos[i*3+2]=keeper.position.z+rand(-70,40)}}rainGeo.attributes.position.needsUpdate=true;
let desired=keeper.position.clone().add(new T.Vector3(Math.sin(yaw)*9,6.5,Math.cos(yaw)*10));camera.position.lerp(desired,1-Math.exp(-dt*7));camera.position.x+=rand(-shake,shake);camera.position.y+=rand(-shake,shake);camera.lookAt(keeper.position.clone().add(new T.Vector3(-Math.sin(yaw)*4,1.5,-Math.cos(yaw)*4)));$('#health').style.width=clamp(health,0,100)+'%';if(health<=0){health=100;keeper.position.set(0,0,19);toast('RISE AGAIN');burst(keeper.position,40)}$('#area').textContent=keeper.position.z< -95?'THE IRON CITADEL':keeper.position.x< -25?'WRECK FIELD':keeper.position.x>25?'CLIFFSIDE FOUNDRY':'THE DROWNED SPAN';if(mode==='siege')ui();renderer.render(scene,camera);

}
camera.position.set(0,7,30);camera.lookAt(0,1,10);frame();
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});

